"""Date-window membership for the date_window fixture."""

from __future__ import annotations

from datetime import datetime


def _validate_and_parse_date(date_str: str) -> datetime:
    """Validate and parse a date string in YYYY-MM-DD format.

    Raises ValueError if the date is malformed or impossible.
    """
    try:
        # Strict parsing: must be exactly YYYY-MM-DD format
        if not isinstance(date_str, str):
            raise ValueError(f"Date must be a string, got {type(date_str)}")

        # Check format: YYYY-MM-DD
        if len(date_str) != 10 or date_str[4] != '-' or date_str[7] != '-':
            raise ValueError(f"Date must be in YYYY-MM-DD format: {date_str}")

        year_str, month_str, day_str = date_str.split('-')

        # Check that each part is exactly the right length and all digits
        if len(year_str) != 4 or not year_str.isdigit():
            raise ValueError(f"Year must be 4 digits: {date_str}")
        if len(month_str) != 2 or not month_str.isdigit():
            raise ValueError(f"Month must be 2 digits with zero padding: {date_str}")
        if len(day_str) != 2 or not day_str.isdigit():
            raise ValueError(f"Day must be 2 digits with zero padding: {date_str}")

        # Parse and validate as a calendar date
        # This will raise ValueError if the date is impossible (e.g., Feb 29 in non-leap year)
        return datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError as e:
        # Re-raise with original message if it's our validation
        if "Date must be" in str(e) or "Year must be" in str(e) or "Month must be" in str(e) or "Day must be" in str(e):
            raise
        # Otherwise, it's from strptime (invalid calendar date)
        raise ValueError(f"Invalid date: {date_str}") from e


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window.

    All dates must be in strict ISO calendar-date form (YYYY-MM-DD).
    Window boundaries are inclusive.
    Raises ValueError if any date is malformed or if any window has start > end.
    """
    # Validate and parse the target date
    target = _validate_and_parse_date(target_date)

    # Validate all windows first (fail-fast on any invalid date or ordering)
    parsed_windows = []
    for start_str, end_str in windows:
        start = _validate_and_parse_date(start_str)
        end = _validate_and_parse_date(end_str)

        # Check that start <= end
        if start > end:
            raise ValueError(f"Window start {start_str} is after end {end_str}")

        parsed_windows.append((start, end))

    # Check if target is in any window
    for start, end in parsed_windows:
        if start <= target <= end:
            return True

    return False
